using System.Data;
using CargoWise.EntityFramework;
using CargoWise.Types;
using Enterprise.Client.UPE.Business.BISI;

namespace Enterprise.Client.UPE.Business
{
    public class ClientXPLDUploadLog : AutoClientXPLDUploadLog
	{
		public ClientXPLDUploadLog(BusinessObjectFactory Factory, DataRow Row)
			: base(Factory, Row)
		{
		}

		ZInt ExceptionResolutionCodePosition
		{
			get
			{
				return ShipmentStatusLine.Length.ShipmentNumber
					+ ShipmentStatusLine.Length.ImportCountry
					+ ShipmentStatusLine.Length.LineType
					+ ShipmentStatusLine.Length.ImportDate
					+ ShipmentStatusLine.Length.ActionType
					+ ShipmentStatusLine.Length.ShipmentStatus
					+ ShipmentStatusLine.Length.HoldReasonCode
					+ ShipmentStatusLine.Length.InspectIndicator
					+ ShipmentStatusLine.Length.AddressCorrectionIndicator
					+ ShipmentStatusLine.Length.ImportReleaseDate
					+ ShipmentStatusLine.Length.CustomsRefNo
					+ ShipmentStatusLine.Length.BrokerCode
					+ ShipmentStatusLine.Length.Remarks
					+ ShipmentStatusLine.Length.ExceptionStatusCode;
			}
		}

		ZInt LengthOfKeyFields
		{
			get
			{
				return ShipmentStatusLine.Length.ShipmentNumber
					+ ShipmentStatusLine.Length.ImportCountry
					+ ShipmentStatusLine.Length.LineType
					+ ShipmentStatusLine.Length.ImportDate
					+ ShipmentStatusLine.Length.ActionType;
			}
		}

		public ZString GetBISIDataWithInsertedXPLDReleaseCode(ZString releaseCode)
		{
			ZString keyFields = U3_BISIData.Left(LengthOfKeyFields);
			ZString anythingBetweenShipmentStatusAndInspectIndicator = U3_BISIData.SubstringSafe(
				LengthOfKeyFields + ShipmentStatusLine.Length.ShipmentStatus,
				ShipmentStatusLine.Length.HoldReasonCode );

            ZString anythingBetweenInspectIndicatorAndCustomsRefNo = U3_BISIData.SubstringSafe(
                LengthOfKeyFields + ShipmentStatusLine.Length.ShipmentStatus + ShipmentStatusLine.Length.HoldReasonCode + ShipmentStatusLine.Length.InspectIndicator,
                 ShipmentStatusLine.Length.AddressCorrectionIndicator + ShipmentStatusLine.Length.ImportReleaseDate);

            ZString result = keyFields + "04" + anythingBetweenShipmentStatusAndInspectIndicator + "0" + anythingBetweenInspectIndicatorAndCustomsRefNo;
			if (result.Length < ExceptionResolutionCodePosition)
			{
				result = result.PadRight(ExceptionResolutionCodePosition, ' ');
			}

			result += releaseCode;
			result = result.PadRight(ExceptionResolutionCodePosition + ShipmentStatusLine.Length.ExceptionResolutionCode + ShipmentStatusLine.Length.Filler, ' ');

			return result;
		}

		protected override void SetDefaultValues()
		{
			base.SetDefaultValues();
			U3_DateCreated = ZDateTime.Now;
		}		
	}
}
